/// # Complexity
///
/// Temporal `O(n)`: one pass over the input, counted in element reads.
/// Spatial `O(1)`: one accumulator word.
pub fn synthetic_heading(x: &[u64]) -> u64 {
    x.iter().sum()
}

/// # Complexity
///
/// Temporal `O(1)` for `n <= 1024` slots: one slot probe per lookup, counted in
/// slot probes; the table never resizes.
/// Spatial `O(1)`: the slot array is fixed at construction.
pub fn synthetic_bounded(n: usize) -> usize {
    n
}

/// # Complexity
///
/// `O(take)` time, `O(1)` extra space.
pub fn synthetic_bare(x: &[i64], take: usize) -> i64 {
    x[0]
}

/// # Complexity
///
/// `O(take)` time, `O(1)` extra space. Accumulates in `i32` with `|x| <= 32*127`.
pub fn synthetic_numerals(x: &[i8], take: usize) -> i32 {
    let mut a = 0i32;
    for v in x.iter().take(take) {
        a += i32::from(*v);
    }
    a
}

/// # Complexity
///
/// Temporal `O(1)`: the three `List.append` recursions traverse 11 cons cells, counted in
/// list links; the shared tail is not traversed.
/// Spatial `O(11)` cons cells for the returned prefix.
pub fn synthetic_numerals_units(rest: &[u64]) -> Vec<u64> {
    rest.to_vec()
}
